-- Nathan Nguyen (profileID=14) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Nathan Nguyen phrasings

SELECT p.argumentID, p.phrasingID, 14, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 14
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 14 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=14 AND targArgID IN (57,59,65,90,94,100,103,104,107,110,145,148,175,200,203,205,217,219,230,267,268,269,270,271,272,275,276,277,289,293,294,295,296,317,321,322,323,349,350,367,368,400,401,402,406,409,412,414,416,420,463,483,500,527,530,539,540,541,547,560,561,574,588,590,591,592,595,596,597,722,736,836,1229);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 14
SET pe.active = o.acceptance
WHERE pe.profileID = 14;

SELECT 'Done: endorsements for profileID=14' AS status;